-- Who Sabi? — PostgreSQL 16 schema (MVP + v1.1 hooks)
-- Conventions: ULID-like text ids generated by the app (sortable), timestamptz in UTC,
-- WAT (Africa/Lagos) applied at the edges only. Soft-delete via status columns.
-- Behavioural analytics (sessions, screens, time spent) live in ClickHouse: see analytics.clickhouse.sql.

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS citext;

-- ===================== IDENTITY =====================
CREATE TYPE age_band AS ENUM ('13_17', '18_plus');
CREATE TYPE user_status AS ENUM ('guest', 'active', 'restricted', 'banned', 'deleted');

CREATE TABLE users (
  id              text PRIMARY KEY,
  username        citext UNIQUE,                       -- null for guests
  display_name    text,
  avatar_id       text,
  status          user_status NOT NULL DEFAULT 'guest',
  age_band        age_band,
  home_state      char(2),                             -- e.g. 'LA','FC','KN' (NG state codes)
  language        text NOT NULL DEFAULT 'en',          -- 'en' | 'pcm' | 'yo' | 'ig' | 'ha'
  family_mode     boolean NOT NULL DEFAULT false,
  data_saver      boolean NOT NULL DEFAULT false,
  discoverable    boolean NOT NULL DEFAULT true,
  level           int NOT NULL DEFAULT 1,
  xp              bigint NOT NULL DEFAULT 0,
  signup_platform text CHECK (signup_platform IN ('android','ios','web')),
  acquisition_source text,                             -- 'organic','invite','creator:<code>','ambassador:<code>','ads:<network>'
  last_seen_at    timestamptz,                         -- written at most every 5 min per user (admin "last seen")
  last_platform   text CHECK (last_platform IN ('android','ios','web')),
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz
);

CREATE TABLE auth_identities (
  id              text PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider        text NOT NULL CHECK (provider IN ('phone','google','apple','guest_device')),
  subject         text NOT NULL,                       -- E.164 phone, Google sub, Apple sub, device id
  phone_hash      bytea,                               -- SHA-256(E.164) for contact discovery
  verified_at     timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, subject)
);
CREATE INDEX ON auth_identities ((substring(phone_hash from 1 for 3))) WHERE phone_hash IS NOT NULL;

CREATE TABLE refresh_tokens (
  id              text PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash      bytea NOT NULL UNIQUE,
  family_id       text NOT NULL,                       -- rotation family for reuse detection
  device_id       text,
  expires_at      timestamptz NOT NULL,
  revoked_at      timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE devices (
  id              text PRIMARY KEY,
  user_id         text REFERENCES users(id) ON DELETE CASCADE,
  platform        text NOT NULL CHECK (platform IN ('android','ios','web')),
  push_token      text,                                -- FCM token (Android, iOS via APNs, web push)
  app_version     text,
  model           text,
  browser         text,                                -- web only, e.g. 'chrome_android', 'safari_ios'
  ram_mb          int,
  last_seen_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE consent_records (
  id              bigserial PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose         text NOT NULL,                       -- 'terms','privacy','analytics','marketing_push','ads_personalisation','contacts','guardian','session_replay'
  granted         boolean NOT NULL,
  policy_version  text NOT NULL,
  source          text NOT NULL,                       -- 'onboarding','settings','web_banner'
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- ===================== SOCIAL =====================
CREATE TABLE friendships (
  user_a          text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  user_b          text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status          text NOT NULL CHECK (status IN ('pending','accepted','blocked')),
  requested_by    text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_a, user_b),
  CHECK (user_a < user_b)                              -- canonical ordering, one row per pair
);

-- ===================== CONTENT =====================
CREATE TYPE question_status AS ENUM ('draft','in_review','approved','live','suspended','retired');
CREATE TYPE question_type AS ENUM ('mcq4','true_false','image_mcq','audio_mcq','closest_number');

CREATE TABLE categories (
  id              text PRIMARY KEY,                    -- 'slang','nollywood','music','food','mixed'
  name_en         text NOT NULL,
  name_pcm        text,
  emoji           text,
  color_hex       char(7),
  sort_order      int NOT NULL DEFAULT 0,
  active          boolean NOT NULL DEFAULT true
);

CREATE TABLE media_assets (
  id              text PRIMARY KEY,
  kind            text NOT NULL CHECK (kind IN ('image','audio')),
  url             text NOT NULL,
  bytes           int NOT NULL CHECK (bytes <= 60000),
  blurhash        text,
  licence         text NOT NULL,                       -- 'own','licensed:<ref>','sponsor:<id>'
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE questions (
  id              text PRIMARY KEY,
  external_ref    text UNIQUE,                         -- e.g. SEED-0001
  category_id     text NOT NULL REFERENCES categories(id),
  subcategory     text,
  type            question_type NOT NULL DEFAULT 'mcq4',
  text            text NOT NULL CHECK (char_length(text) <= 160),
  options         jsonb NOT NULL,                      -- ["..","..",..] canonical order
  correct_index   smallint,                            -- null for closest_number
  numeric_answer  numeric,                             -- closest_number only (options = [])
  fact            text CHECK (char_length(fact) <= 200),
  media_id        text REFERENCES media_assets(id),
  difficulty      smallint NOT NULL CHECK (difficulty BETWEEN 1 AND 5),
  d_rating        real NOT NULL DEFAULT 1500,          -- calibrated item difficulty
  family_safe     boolean NOT NULL DEFAULT true,
  region_tag      text,                                -- 'SW','SE','SS','N','NC','ALL'
  language        text NOT NULL DEFAULT 'en',
  valid_from      date,
  valid_until     date,
  source_url      text,
  status          question_status NOT NULL DEFAULT 'draft',
  author_id       text,                                -- staff or user (Question Factory)
  reviewed_by     text,
  version         int NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CHECK (jsonb_typeof(options) = 'array'),
  CONSTRAINT questions_answer_check CHECK (
    CASE WHEN type = 'closest_number'
      THEN numeric_answer IS NOT NULL AND correct_index IS NULL AND jsonb_array_length(options) = 0
      ELSE correct_index IS NOT NULL AND correct_index >= 0 AND correct_index < jsonb_array_length(options)
    END
  )
);
CREATE INDEX questions_serve_idx ON questions (category_id, status, difficulty) WHERE status = 'live';
CREATE INDEX questions_text_trgm ON questions USING gin (text gin_trgm_ops);

CREATE TABLE question_stats (
  question_id     text PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
  plays           bigint NOT NULL DEFAULT 0,
  correct         bigint NOT NULL DEFAULT 0,
  option_counts   int[] NOT NULL DEFAULT '{0,0,0,0}',  -- canonical order, for "Ask Naija"
  avg_elapsed_ms  int,
  reports         int NOT NULL DEFAULT 0,
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE question_reports (
  id              bigserial PRIMARY KEY,
  question_id     text NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
  user_id         text REFERENCES users(id) ON DELETE SET NULL,
  reason          text NOT NULL CHECK (reason IN ('wrong_answer','outdated','offensive','typo','unfair','other')),
  note            text,
  resolution      text CHECK (resolution IN ('fixed','rejected','retired')),
  resolved_by     text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  resolved_at     timestamptz,
  UNIQUE (question_id, user_id)
);

CREATE TABLE packs (
  id              text PRIMARY KEY,
  slug            text UNIQUE NOT NULL,
  title           text NOT NULL,
  description     text,
  cover_media_id  text REFERENCES media_assets(id),
  access          text NOT NULL CHECK (access IN ('free','coins','pass','sponsored')),
  price_coins     int,
  sponsor_id      text,
  starts_at       timestamptz,
  ends_at         timestamptz,
  active          boolean NOT NULL DEFAULT true
);

CREATE TABLE pack_questions (
  pack_id         text NOT NULL REFERENCES packs(id) ON DELETE CASCADE,
  question_id     text NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
  PRIMARY KEY (pack_id, question_id)
);

-- Seen-history fallback (primary is Redis bloom per user). Partition monthly in prod.
CREATE TABLE user_question_seen (
  user_id         text NOT NULL,
  question_id     text NOT NULL,
  seen_at         timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, question_id)
);

-- ===================== RATINGS =====================
CREATE TABLE ratings (
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  scope           text NOT NULL,                       -- 'overall' or category id
  rating          real NOT NULL DEFAULT 1500,
  rd              real NOT NULL DEFAULT 350,           -- Glicko-2 rating deviation
  volatility      real NOT NULL DEFAULT 0.06,
  games           int NOT NULL DEFAULT 0,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, scope)
);

-- ===================== DUELS =====================
CREATE TYPE duel_state AS ENUM ('created','wait_b_r1r2','wait_a_r2r3','wait_b_r3','tiebreak','complete','forfeit','declined','cancelled');

CREATE TABLE duels (
  id              text PRIMARY KEY,
  player_a        text NOT NULL REFERENCES users(id),
  player_b        text REFERENCES users(id),           -- null until invite link accepted
  invite_token    text UNIQUE,
  source          text NOT NULL CHECK (source IN ('friend','random','rematch','link','bot')),
  state           duel_state NOT NULL DEFAULT 'created',
  turn_user_id    text,
  turn_deadline   timestamptz,
  score_a         int NOT NULL DEFAULT 0,
  score_b         int NOT NULL DEFAULT 0,
  winner_id       text,
  rating_delta_a  real,
  rating_delta_b  real,
  rematch_of      text UNIQUE REFERENCES duels(id),    -- one rematch per finished duel
  created_at      timestamptz NOT NULL DEFAULT now(),
  completed_at    timestamptz,
  CONSTRAINT duels_players_check CHECK (player_b IS NULL OR player_b <> player_a)
);
CREATE INDEX duels_player_a_idx ON duels (player_a, state);
CREATE INDEX duels_player_b_idx ON duels (player_b, state);
CREATE INDEX duels_deadline_idx ON duels (turn_deadline) WHERE state IN ('created','wait_b_r1r2','wait_a_r2r3','wait_b_r3','tiebreak');

CREATE TABLE duel_rounds (
  duel_id         text NOT NULL REFERENCES duels(id) ON DELETE CASCADE,
  round_no        smallint NOT NULL CHECK (round_no BETWEEN 1 AND 4),  -- 4 = tiebreak
  category_id     text REFERENCES categories(id),
  picked_by       text,
  offered         text[] NOT NULL,                     -- 3 category ids offered
  question_ids    text[] NOT NULL,
  PRIMARY KEY (duel_id, round_no)
);

CREATE TABLE duel_answers (
  duel_id           text NOT NULL REFERENCES duels(id) ON DELETE CASCADE,
  round_no          smallint NOT NULL,
  seq               smallint NOT NULL,
  user_id           text NOT NULL REFERENCES users(id),
  question_id       text NOT NULL REFERENCES questions(id),
  served_at         timestamptz NOT NULL,
  received_at       timestamptz,
  client_elapsed_ms int,
  accepted_elapsed_ms int,
  rtt_est_ms        int,
  display_index     smallint,                          -- what the user tapped
  chosen_index      smallint,                          -- canonical
  correct           boolean,
  points            int NOT NULL DEFAULT 0,
  lifeline          text,
  platform          text CHECK (platform IN ('android','ios','web')),
  tab_hidden_ms     int,                               -- web only: time the tab was hidden during the question (integrity signal)
  guess             numeric,                           -- tie-break (round 4) only
  idempotency_key   text,                              -- of the request that answered; a retry with another key gets 409
  PRIMARY KEY (duel_id, round_no, seq, user_id)
);

-- ===================== PARTY =====================
CREATE TABLE party_games (
  id              text PRIMARY KEY,
  room_code       char(5) NOT NULL,
  host_user_id    text REFERENCES users(id),
  settings        jsonb NOT NULL,                      -- {questions, timer_s, packs[], family_safe}
  player_count    int NOT NULL,
  started_at      timestamptz NOT NULL,
  ended_at        timestamptz
);
CREATE INDEX ON party_games (room_code, started_at DESC);

CREATE TABLE party_results (
  game_id         text NOT NULL REFERENCES party_games(id) ON DELETE CASCADE,
  player_ref      text NOT NULL,                       -- user id or 'guest:<nick>#<n>'
  user_id         text REFERENCES users(id),
  rank            int NOT NULL,
  score           int NOT NULL,
  correct_count   int NOT NULL,
  PRIMARY KEY (game_id, player_ref)
);

-- ===================== DAILY =====================
CREATE TABLE daily_challenges (
  id              int PRIMARY KEY,                     -- sequential number (#142)
  play_date       date UNIQUE NOT NULL,                -- WAT date
  question_ids    text[] NOT NULL CHECK (array_length(question_ids,1) = 7),
  locked          boolean NOT NULL DEFAULT false
);

CREATE TABLE daily_results (
  daily_id        int NOT NULL REFERENCES daily_challenges(id),
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  correct_count   smallint NOT NULL,
  score           int NOT NULL,
  total_ms        int NOT NULL,
  grid            text NOT NULL,                       -- e.g. 'GGGRGGG'
  home_state      char(2),
  completed_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (daily_id, user_id)
);

CREATE TABLE streaks (
  user_id         text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  current         int NOT NULL DEFAULT 0,
  best            int NOT NULL DEFAULT 0,
  last_play_date  date,
  freezes_left    smallint NOT NULL DEFAULT 1,
  freeze_week     text                                 -- ISO week the freeze counter belongs to
);

-- ===================== LEAGUES (v1.1) =====================
CREATE TABLE leagues (
  id              text PRIMARY KEY,
  name            text NOT NULL,
  owner_id        text NOT NULL REFERENCES users(id),
  invite_code     text UNIQUE NOT NULL,
  kind            text NOT NULL CHECK (kind IN ('group','campus')),
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE league_members (
  league_id       text NOT NULL REFERENCES leagues(id) ON DELETE CASCADE,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role            text NOT NULL DEFAULT 'member',
  joined_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (league_id, user_id)
);
CREATE TABLE league_week_scores (
  league_id       text NOT NULL REFERENCES leagues(id) ON DELETE CASCADE,
  iso_week        text NOT NULL,                       -- '2026-W42'
  user_id         text NOT NULL,
  points          int NOT NULL,
  rank            int,
  PRIMARY KEY (league_id, iso_week, user_id)
);

-- ===================== ECONOMY =====================
-- Double-entry ledger. Every movement has two rows summing to zero per currency.
CREATE TABLE ledger_accounts (
  id              text PRIMARY KEY,                    -- 'user:<id>:coins', 'system:rewards:coins', 'system:shop:coins'
  owner_user_id   text REFERENCES users(id) ON DELETE CASCADE,
  currency        text NOT NULL CHECK (currency IN ('coins','gems')),
  balance         bigint NOT NULL DEFAULT 0,           -- cached; verified nightly from entries
  CHECK (owner_user_id IS NULL OR balance >= 0)
);
CREATE TABLE ledger_transactions (
  id              text PRIMARY KEY,
  idempotency_key text UNIQUE NOT NULL,
  reason          text NOT NULL,                       -- 'duel_win','daily','rewarded_ad','lifeline','iap','refund','admin_grant',...
  ref_type        text,
  ref_id          text,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ledger_entries (
  id              bigserial PRIMARY KEY,
  transaction_id  text NOT NULL REFERENCES ledger_transactions(id),
  account_id      text NOT NULL REFERENCES ledger_accounts(id),
  amount          bigint NOT NULL,                     -- +credit / -debit
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON ledger_entries (account_id, created_at DESC);

CREATE TABLE ad_rewards (
  reward_ref      text PRIMARY KEY,                    -- AdMob SSV transaction_id, or the server-issued web ad session id (dedupe)
  source          text NOT NULL DEFAULT 'admob_ssv' CHECK (source IN ('admob_ssv','web_ad_session')),
  user_id         text NOT NULL REFERENCES users(id),
  ad_unit         text NOT NULL,
  reward_item     text NOT NULL,
  reward_amount   int NOT NULL,
  ledger_tx_id    text REFERENCES ledger_transactions(id),
  received_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE entitlements (
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  entitlement     text NOT NULL,                       -- 'sabi_pass'
  source          text NOT NULL,                       -- 'revenuecat' (stores), 'paystack' (web), 'admin_grant'
  expires_at      timestamptz,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, entitlement)
);

CREATE TABLE purchases (
  id              text PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id),
  store           text NOT NULL CHECK (store IN ('play','app_store','paystack')),  -- 'paystack' = web purchases (v1.1)
  product_id      text NOT NULL,
  store_tx_id     text UNIQUE NOT NULL,                -- store order id, or the Paystack transaction reference
  price_micros    bigint,
  currency        char(3),
  status          text NOT NULL CHECK (status IN ('completed','refunded','pending')),
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE cosmetics (
  id              text PRIMARY KEY,
  slot            text NOT NULL CHECK (slot IN ('outfit','frame','emote','button_skin','sound_pack','title')),
  name            text NOT NULL,
  price_coins     int,
  price_gems      int,
  requires_pass   boolean NOT NULL DEFAULT false,
  media_id        text REFERENCES media_assets(id),
  active          boolean NOT NULL DEFAULT true
);
CREATE TABLE user_inventory (
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  cosmetic_id     text NOT NULL REFERENCES cosmetics(id),
  equipped        boolean NOT NULL DEFAULT false,
  acquired_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, cosmetic_id)
);

-- ===================== SPONSORS & PRIZES (v2) =====================
CREATE TABLE sponsors (
  id              text PRIMARY KEY,
  name            text NOT NULL,
  contact_email   text,
  contract_ref    text
);
CREATE TABLE prize_events (
  id              text PRIMARY KEY,
  sponsor_id      text NOT NULL REFERENCES sponsors(id),
  title           text NOT NULL,
  rules_url       text NOT NULL,                       -- published official rules (required)
  purchase_independent boolean NOT NULL DEFAULT true CHECK (purchase_independent),
  eligible_age    age_band NOT NULL DEFAULT '18_plus',
  starts_at       timestamptz NOT NULL,
  ends_at         timestamptz NOT NULL,
  prize_pool_desc text NOT NULL,
  states_excluded char(2)[] NOT NULL DEFAULT '{}'      -- per-state legal review
);
CREATE TABLE prize_claims (
  id              text PRIMARY KEY,
  event_id        text NOT NULL REFERENCES prize_events(id),
  user_id         text NOT NULL REFERENCES users(id),
  prize_kind      text NOT NULL CHECK (prize_kind IN ('airtime','data','merch')),
  amount_ngn      int,
  msisdn_last4    char(4),
  provider_ref    text,
  status          text NOT NULL CHECK (status IN ('pending','sent','failed','void')),
  created_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, user_id)
);

-- ===================== OPS / COMPLIANCE =====================
CREATE TABLE moderation_actions (
  id              bigserial PRIMARY KEY,
  target_user_id  text REFERENCES users(id),
  action          text NOT NULL CHECK (action IN ('warn','mute','rename','ban','unban','shadow_restrict')),
  reason          text NOT NULL,
  actor           text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- Every admin action AND every look at a user's data. Append-only; the app role has INSERT and SELECT only.
CREATE TABLE admin_audit_log (
  id              bigserial PRIMARY KEY,
  actor           text NOT NULL,                       -- admin_users.id, or 'system'
  action          text NOT NULL,                       -- 'view_user','reveal_pii','export','grant_coins','ban','edit_question','publish_config',...
  entity          text NOT NULL,
  entity_id       text,
  reason          text,                                -- required for reveal_pii, export and grants
  before          jsonb,
  after           jsonb,
  ip              inet,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON admin_audit_log (entity, entity_id, created_at DESC);
CREATE INDEX ON admin_audit_log (actor, created_at DESC);

CREATE TABLE dsar_requests (
  id              text PRIMARY KEY,
  user_id         text NOT NULL,
  kind            text NOT NULL CHECK (kind IN ('access','erasure','rectification','portability','objection')),
  status          text NOT NULL CHECK (status IN ('received','in_progress','completed','rejected')),
  due_at          timestamptz NOT NULL,                -- received + 30 days
  completed_at    timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app_config (
  key             text PRIMARY KEY,
  value           jsonb NOT NULL,
  updated_by      text,
  updated_at      timestamptz NOT NULL DEFAULT now()
);

-- ===================== ADMIN CONSOLE (doc 18) =====================
-- Staff accounts. Sign-in is Google Workspace SSO with 2-step verification enforced; no passwords are stored.
CREATE TABLE admin_users (
  id              text PRIMARY KEY,
  email           citext UNIQUE NOT NULL,
  name            text NOT NULL,
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','removed')),
  last_login_at   timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE admin_role_grants (
  admin_id        text NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  role            text NOT NULL CHECK (role IN ('owner','admin','analyst','growth','liveops','editor','fact_checker','writer',
                                                'moderator','support','finance','sponsor_manager','dpo','engineer','viewer')),
  granted_by      text NOT NULL REFERENCES admin_users(id),
  approved_by     text REFERENCES admin_users(id),     -- second approver for privileged roles (four-eyes)
  expires_at      timestamptz,                         -- time-boxed access, e.g. contractors
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (admin_id, role),
  CHECK (approved_by IS NULL OR approved_by NOT IN (granted_by, admin_id))  -- nobody approves their own grant
);

-- Internal notes on a player (support and moderation context). Never shown to the player.
CREATE TABLE user_notes (
  id              bigserial PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  author_id       text NOT NULL REFERENCES admin_users(id),
  body            text NOT NULL CHECK (char_length(body) <= 2000),
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON user_notes (user_id, created_at DESC);

-- Anti-cheat and abuse signals waiting for a human decision (doc 10 §2).
CREATE TABLE integrity_flags (
  id              bigserial PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind            text NOT NULL CHECK (kind IN ('accuracy_outlier','timing_anomaly','tab_hidden','multi_account',
                                                'collusion','ad_reward_abuse','question_scraping','otp_abuse')),
  score           real NOT NULL CHECK (score BETWEEN 0 AND 1),  -- risk score from the nightly job
  evidence        jsonb NOT NULL,                      -- e.g. {"z": 4.1, "answers": 180, "median_ms": 900}
  status          text NOT NULL DEFAULT 'open' CHECK (status IN ('open','dismissed','actioned')),
  reviewed_by     text REFERENCES admin_users(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  reviewed_at     timestamptz
);
CREATE INDEX ON integrity_flags (score DESC) WHERE status = 'open';

-- Feature flags and kill switches, evaluated on the server and cached in Redis (cfg:*).
CREATE TABLE feature_flags (
  key             text PRIMARY KEY,                    -- 'party.enabled', 'web.ads.enabled', 'shop.enabled'
  description     text NOT NULL,
  enabled         boolean NOT NULL DEFAULT false,      -- master switch; false overrides every rule
  rules           jsonb NOT NULL DEFAULT '[]',         -- [{"platform":"web","min_app_version":"1.2.0","percent":10}]
  updated_by      text REFERENCES admin_users(id),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

-- A/B tests. Assignment = hash(experiment key, user id) into the variant weights; exposures are logged as events.
CREATE TABLE experiments (
  key             text PRIMARY KEY,                    -- 'taste_test_length'
  hypothesis      text NOT NULL,
  primary_metric  text NOT NULL,                       -- metric id from doc 18 §10
  guardrails      text[] NOT NULL DEFAULT '{d7_retention,crash_free_sessions,reports_per_1k}',
  variants        jsonb NOT NULL,                      -- [{"key":"control","weight":50},{"key":"five_q","weight":50}]
  audience        jsonb NOT NULL DEFAULT '{}',         -- {"platform":["android","web"],"new_users_only":true}
  status          text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','running','stopped','shipped')),
  owner_id        text REFERENCES admin_users(id),
  started_at      timestamptz,
  stopped_at      timestamptz
);

-- Every remote-config change, so any value can be rolled back.
CREATE TABLE config_history (
  id              bigserial PRIMARY KEY,
  key             text NOT NULL,
  old_value       jsonb,
  new_value       jsonb NOT NULL,
  changed_by      text NOT NULL REFERENCES admin_users(id),
  reason          text,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON config_history (key, created_at DESC);

-- Saved player segments ("played 5+ duels this week, Lagos, Android"). The definition compiles to ClickHouse SQL.
CREATE TABLE segments (
  id              text PRIMARY KEY,
  name            text NOT NULL,
  definition      jsonb NOT NULL,
  created_by      text NOT NULL REFERENCES admin_users(id),
  last_count      int,
  last_computed_at timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- Push campaigns to a segment (v1.1). Quiet hours and frequency caps (TRD FR-NOT-2) always apply.
CREATE TABLE push_campaigns (
  id              text PRIMARY KEY,
  name            text NOT NULL,
  segment_id      text NOT NULL REFERENCES segments(id),
  template        jsonb NOT NULL,                      -- {"en":{"title":"..","body":".."},"pcm":{...},"deeplink":"whosabi://daily"}
  send_at         timestamptz,
  status          text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_approval','scheduled','sending','sent','cancelled')),
  audience_count  int,
  created_by      text NOT NULL REFERENCES admin_users(id),
  approved_by     text REFERENCES admin_users(id),     -- needed above the approval threshold (doc 18 §8)
  created_at      timestamptz NOT NULL DEFAULT now(),
  CHECK (approved_by IS NULL OR approved_by <> created_by)
);

-- KPI alerts to email or Slack, e.g. OTP success < 85% for 15 min, DAU down 20% vs the same hour last week.
CREATE TABLE alert_rules (
  id              text PRIMARY KEY,
  metric          text NOT NULL,                       -- metric id from doc 18 §10
  comparison      text NOT NULL CHECK (comparison IN ('below','above','drop_pct_vs_last_week')),
  threshold       numeric NOT NULL,
  window_minutes  int NOT NULL DEFAULT 60,
  channels        text[] NOT NULL DEFAULT '{email}',   -- 'email','slack'
  enabled         boolean NOT NULL DEFAULT true,
  created_by      text NOT NULL REFERENCES admin_users(id),
  created_at      timestamptz NOT NULL DEFAULT now()
);

